const fs = require('fs');
const http = require('http');
const https = require('https');
const tls = require('tls');

const creds = JSON.parse(fs.readFileSync('email_credentials.json', 'utf8'));
const apiKey = creds.account.api_key;
const userEmail = creds.account.email;
const TARGET_HOST = 'agenskill.onrender.com';
const TARGET_PORT = 443;
const PATH = '/contacts';

const proxyEnv = process.env.https_proxy || process.env.HTTPS_PROXY || process.env.http_proxy || process.env.HTTP_PROXY;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function requestViaProxy(proxyUrl, path) {
  return new Promise((resolve, reject) => {
    const proxy = new URL(proxyUrl);
    const connectReq = http.request({
      host: proxy.hostname,
      port: proxy.port || 80,
      method: 'CONNECT',
      path: `${TARGET_HOST}:${TARGET_PORT}`,
      headers: { Host: `${TARGET_HOST}:${TARGET_PORT}` },
    });

    connectReq.on('connect', (res, socket) => {
      if (res.statusCode !== 200) {
        socket.destroy();
        return reject(new Error(`Proxy CONNECT failed with status ${res.statusCode}`));
      }
      const tlsSocket = tls.connect({
        socket,
        servername: TARGET_HOST,
      }, () => {
        const req = https.request({
          host: TARGET_HOST,
          port: TARGET_PORT,
          path,
          method: 'GET',
          headers: {
            'X-API-Key': apiKey,
            'X-User-Email': userEmail,
          },
          createConnection: () => tlsSocket,
        });
        req.on('response', (res2) => {
          let body = '';
          res2.on('data', (c) => (body += c));
          res2.on('end', () => resolve({ status: res2.statusCode, body }));
        });
        req.on('error', reject);
        req.end();
      });
      tlsSocket.on('error', reject);
    });
    connectReq.on('error', reject);
    connectReq.end();
  });
}

function requestDirect() {
  return new Promise((resolve, reject) => {
    const req = https.request({
      host: TARGET_HOST,
      port: TARGET_PORT,
      path: PATH,
      method: 'GET',
      headers: {
        'X-API-Key': apiKey,
        'X-User-Email': userEmail,
      },
    });
    req.on('response', (res) => {
      let body = '';
      res.on('data', (c) => (body += c));
      res.on('end', () => resolve({ status: res.statusCode, body }));
    });
    req.on('error', reject);
    req.end();
  });
}

async function main() {
  let result = null;
  let lastErr = null;

  // Attempt 1: direct (works when network allows)
  try {
    result = await requestDirect();
  } catch (err) {
    lastErr = err;
  }

  // Attempts 2-4: through proxy if configured
  if (!result && proxyEnv) {
    for (let attempt = 1; attempt <= 3 && !result; attempt++) {
      try {
        result = await requestViaProxy(proxyEnv, PATH);
      } catch (err) {
        lastErr = err;
        if (attempt < 3) await sleep(2000 * attempt);
      }
    }
  }

  if (!result) {
    console.error('All attempts failed:', lastErr && lastErr.message);
    process.exit(1);
  }

  let data;
  try {
    data = JSON.parse(result.body);
  } catch (e) {
    console.error(`Non-JSON response (status ${result.status}):`, result.body.slice(0, 500));
    process.exit(1);
  }

  if (result.status >= 400) {
    console.error(JSON.stringify(data, null, 2));
    process.exit(1);
  }

  console.log(JSON.stringify({ success: true, count: data.contacts ? data.contacts.length : 0, contacts: data.contacts || [] }, null, 2));
}

main();

